    { compile_variable($1, $4, $6, $7, vpiLogicVar, false, $3); }

| T_LABEL K_VAR_S local_flag T_STRING ',' signed_t_number signed_t_number ';'
    { compile_variable($1, $4, $6, $7, vpiLogicVar, true, $3); }

